#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Vault viewer, Milestone 1 (#13): one-time Cloudflare + Access setup, then the
# first manual deploy. Real vault content is uploaded only after an automated
# check proves Access turns away unauthenticated requests (ADR-0002).
# Re-run any time to re-check protection (e.g. after changing Pages settings).
# Stage 9 (optional, #31) sets up shared pages: the SHARE_SECRET build secret
# and an Access application that lets only /s/ through (ADR-0006).
# Run from anywhere inside the repo: scripts/deploy-m1-wizard.sh

TOTAL_STAGES=10

# Pinned: an exact wrangler release, used everywhere below.
WRANGLER="wrangler@4.160.0"
wr() { bunx "$WRANGLER" "$@"; }

UA="vault-viewer-check/1.0"
PLACEHOLDER_MARK="vault-viewer-placeholder-7f3a"
CHECK_BRANCH="access-check"

cd "$(dirname "$0")/.."
[[ -f package.json && -f public/_headers ]] || { printf 'Run this from the vault-viewer repo.\n'; exit 1; }

# _host_of URL: the hostname of an absolute URL (lowercased, no port/userinfo).
_host_of() {
  local rest="${1#*://}"
  rest="${rest%%[/?#]*}"; rest="${rest##*@}"; rest="${rest%%:*}"
  printf '%s' "${rest,,}"
}

# access_gate HOST: every URL must be turned away by Access, never served.
# Automatic pass only for a redirect to a *.cloudflareaccess.com host. A bare
# 401/403 (could be Browser Integrity Check or another block) needs a human
# to confirm they see the Access login. Anything else stops the wizard.
access_gate() {
  local host="$1" url code loc body loc_host failed=0
  for url in "https://$host/" "https://$host/robots.txt" "https://$CHECK_BRANCH.$host/"; do
    body=$(mktemp)
    read -r code loc < <(curl -s -A "$UA" -o "$body" -w '%{http_code} %{redirect_url}\n' --max-time 20 "$url" || printf '000\n')
    loc_host=""
    [[ -n "${loc:-}" ]] && loc_host=$(_host_of "$loc")
    if [[ "$code" == "200" ]] || grep -q "$PLACEHOLDER_MARK" "$body"; then
      printf '  %s✗ %s → %s (served without login!)%s\n' "$RED" "$url" "$code" "$RESET"
      failed=1
    elif [[ "$code" =~ ^30[1-8]$ && "$loc_host" == *.cloudflareaccess.com ]]; then
      printf '  %s✓ %s → %s to %s%s\n' "$GREEN" "$url" "$code" "$loc_host" "$RESET"
    elif [[ "$code" =~ ^(401|403)$ ]]; then
      printf '  %s? %s → %s with no redirect to Access%s\n' "$YELLOW" "$url" "$code" "$RESET"
      if confirm "Open $url in a private/incognito window: do you see the Cloudflare Access login page (not the placeholder, not an error)?"; then
        printf '  %s✓ %s confirmed by you%s\n' "$GREEN" "$url" "$RESET"
      else
        failed=1
      fi
    else
      printf '  %s✗ %s → %s %s (not an Access login; treated as not protected)%s\n' "$RED" "$url" "$code" "${loc_host:-}" "$RESET"
      failed=1
    fi
    rm -f "$body"
  done
  if (( failed )); then
    printf '\n  %s%sSTOP: the site is reachable without logging in. Do not deploy vault content.%s\n' "$BOLD" "$RED" "$RESET"
    note "Fix the Access applications (stage 7), wait a minute, then re-run this wizard."
    exit 1
  fi
}

# share_gate HOST: /s/ must be let through without a login (ADR-0006). The
# rest of the site is checked by access_gate, which must still pass.
share_gate() {
  local host="$1" code loc loc_host=""
  read -r code loc < <(curl -s -A "$UA" -o /dev/null -w '%{http_code} %{redirect_url}\n' --max-time 20 "https://$host/s/" || printf '000\n')
  [[ -n "${loc:-}" ]] && loc_host=$(_host_of "$loc")
  if [[ "$loc_host" == *.cloudflareaccess.com || "$code" == "000" ]]; then
    printf '  %s✗ https://%s/s/ → %s %s (not let through)%s\n' "$RED" "$host" "$code" "$loc_host" "$RESET"
    warn "Check the /s/ application's path and its Bypass policy, wait a minute, then re-run."
    SKIPPED+=("Shared pages: /s/ still asks for a login; fix the /s/ Access application")
  else
    printf '  %s✓ https://%s/s/ → %s without a login%s\n' "$GREEN" "$host" "$code" "$RESET"
  fi
}

banner "Vault viewer: Cloudflare + Access setup and first deploy (#13)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare account + Zero Trust Free"
say "Zero Trust is what puts a GitHub login in front of the whole site."
open_url "https://one.dash.cloudflare.com/"
step "Log in (or sign up) to Cloudflare. Turn on two-factor auth for the account if it isn't already."
step "Open Zero Trust and complete onboarding: choose a team name, then pick the Zero Trust Free plan."
note "Onboarding asks for payment details even for Free; the Free plan is not charged."
step "You can find the team name later at Zero Trust > Settings > Team name and domain."
ask CF_ACCESS_TEAM "Your team name (the part before .cloudflareaccess.com):"
[[ -n "$CF_ACCESS_TEAM" ]] || { warn "A team name is required."; exit 1; }
write_env CF_ACCESS_TEAM "$CF_ACCESS_TEAM"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Billing alert (best effort)"
say "Goal: hear about any charge immediately. Nothing in Milestone 1 is billable."
open_url "https://dash.cloudflare.com/?to=/:account/notifications"
step "Go to Alerts (Notifications) > Platform Notifications > Create a Notification."
step "Look for a billing / usage notification (Cloudflare calls one 'Usage Based Billing')."
step "If one is offered for your account, create it with the lowest threshold it allows."
warn "Cloudflare's docs say Usage Based Billing needs a Pay-as-you-go/Pro account and"
warn "uses per-product usage thresholds, not a dollar amount. If it isn't offered, skip."
note "Revisit before Milestone 5 (R2), the first feature that can bill."
SKIPPED+=("Billing alert: revisit before Milestone 5 (R2) if none could be created now")
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub as the only login method"
TEAM_DOMAIN="https://$CF_ACCESS_TEAM.cloudflareaccess.com"
say "First a GitHub OAuth app, then plug it into Zero Trust."
open_url "https://github.com/settings/applications/new"
step "Application name: anything you'll recognise, e.g. 'Vault viewer login'."
step "Homepage URL:   $TEAM_DOMAIN"
step "Callback URL:   $TEAM_DOMAIN/cdn-cgi/access/callback"
step "Register, copy the Client ID, then 'Generate a new client secret' and copy it."
note "Paste the secret straight into Cloudflare in the next step. This wizard never stores it."
pause "Done creating the OAuth app? Press Enter"
open_url "https://one.dash.cloudflare.com/"
step "Zero Trust > Integrations > Identity providers > Add new identity provider > GitHub."
step "App ID = the Client ID; Client secret = the secret. Save, then Finish setup / Authorize."
step "Back in the Identity providers list, click Test next to GitHub: it should show your account."
step "If 'One-time PIN' is in the list, delete it so GitHub is the only way in."
note "(The exact delete button label isn't in Cloudflare's docs; it's on that row.)"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Log wrangler in to Cloudflare"
say "wrangler ($WRANGLER) uploads the site. Logging in opens a browser to authorise."
if wr whoami 2>/dev/null | grep -qi "you are logged in"; then
  printf '  %s✓ already logged in%s\n' "$GREEN" "$RESET"
elif confirm "Run '$WRANGLER login' now?"; then
  wr login
else
  warn "wrangler must be logged in for the next stages."; exit 1
fi
wr whoami | sed 's/^/  /'
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Create the Pages project (direct upload)"
ask CF_PAGES_PROJECT "Pages project name (Enter for vault-viewer):"
CF_PAGES_PROJECT="${CF_PAGES_PROJECT:-vault-viewer}"
write_env CF_PAGES_PROJECT "$CF_PAGES_PROJECT"
if create_out=$(wr pages project create "$CF_PAGES_PROJECT" --production-branch main 2>&1); then
  printf '%s\n' "$create_out" | sed 's/^/  /'
elif grep -qi "already exists" <<<"$create_out"; then
  printf '%s\n' "$create_out" | sed 's/^/  /'
  printf '  %s✓ project %s already exists; reusing it%s\n' "$GREEN" "$CF_PAGES_PROJECT" "$RESET"
else
  printf '%s\n' "$create_out" | sed 's/^/  /'
  warn "Creating the project failed (see above)."; exit 1
fi
note "If that hostname was taken, Cloudflare adds a suffix (e.g. vault-viewer-abc.pages.dev)."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Open the project and read its *.pages.dev hostname."
ask CF_PAGES_HOST "The project's hostname, e.g. $CF_PAGES_PROJECT.pages.dev:"
CF_PAGES_HOST="${CF_PAGES_HOST#https://}"; CF_PAGES_HOST="${CF_PAGES_HOST%%/*}"
[[ "$CF_PAGES_HOST" == *.pages.dev ]] || { warn "Expected a *.pages.dev hostname."; exit 1; }
write_env CF_PAGES_HOST "$CF_PAGES_HOST"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Deploy a placeholder (no vault content)"
say "A harmless page goes up first, so we can prove Access hides it before real notes go up."
PH_DIR=$(mktemp -d)
cp public/_headers public/robots.txt "$PH_DIR/"
printf '<!doctype html><meta charset="utf-8"><meta name="robots" content="noindex, nofollow"><title>Placeholder</title><p>Placeholder. %s</p>\n' "$PLACEHOLDER_MARK" > "$PH_DIR/index.html"
wr pages deploy "$PH_DIR" --project-name "$CF_PAGES_PROJECT" --branch main
say "Also a preview deployment, so previews get checked too ($CHECK_BRANCH.$CF_PAGES_HOST):"
wr pages deploy "$PH_DIR" --project-name "$CF_PAGES_PROJECT" --branch "$CHECK_BRANCH"
rm -rf "$PH_DIR"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Put Access in front of production and previews"
ask OWNER_EMAIL "The email address your GitHub account uses (shown below, not saved):"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Workers & Pages > $CF_PAGES_PROJECT > Settings > 'Enable access policy'."
step "Click Manage on the policy it created (this jumps to Zero Trust > Access > Applications)."
step "Open that application > Configure. Under Public hostname > Subdomain, delete the '*' so it covers $CF_PAGES_HOST. Save."
note "If saving errors, change the Application name (e.g. append ' (production)') and save again."
step "Its policy: Action Allow; Include > Emails > $OWNER_EMAIL. Nothing else."
warn "Never use Include > 'Login Methods: One-time PIN': it lets anyone with an email in."
step "Application > Session Duration: 1 month (the maximum). Save."
step "Back to Workers & Pages > $CF_PAGES_PROJECT > Settings > General: select 'Enable access policy' again (re-protects previews)."
step "Give that preview application the same Emails rule and 1-month session."
step "Check Zero Trust > Access > Applications shows TWO apps: $CF_PAGES_HOST and *.$CF_PAGES_HOST."
pause "Both applications in place? Press Enter to test them"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Prove strangers are turned away"
say "Requesting the site with no login: each must redirect to *.cloudflareaccess.com, never show the placeholder."
note "A 401/403 without that redirect asks you to check in a private window before continuing."
note "Access changes can take a minute to apply. If this fails straight away, wait and re-run."
access_gate "$CF_PAGES_HOST"
printf '\n  %s✓ Access is protecting production, robots.txt and previews.%s\n' "$GREEN" "$RESET"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Shared pages outside Access (optional)"
say "A note with 'share: true' gets a page at /s/<token>/ that anyone with the link can read (ADR-0006)."
say "It takes a build secret that makes the links unguessable, and an Access application that lets /s/ through."
SHARE_SECRET=""
if confirm "Set up sharing now? (Skip it and nothing is ever shared; re-run this wizard later to add it.)"; then
  note "The secret signs every shared link. The same secret keeps links stable across deploys; a new one"
  note "revokes every shared link at once. Keep it in your password manager: this wizard never saves it."
  ask_secret SHARE_SECRET "Paste your existing share secret (Enter generates a new one):"
  if [[ -z "$SHARE_SECRET" ]]; then
    SHARE_SECRET=$(openssl rand -base64 32)
    say "A new secret. Copy it into your password manager now, then clear your scrollback:"
    printf '\n    %s\n\n' "$SHARE_SECRET"
    pause "Saved it? Press Enter"
  fi
  (( ${#SHARE_SECRET} >= 32 )) || { warn "The secret must be at least 32 characters (the build refuses a shorter one)."; exit 1; }
  set_secret SHARE_SECRET "$SHARE_SECRET"
  note "(For the deploy workflow. This run's build below gets it directly.)"
  open_url "https://one.dash.cloudflare.com/"
  step "Zero Trust > Access > Applications > Add an application > Self-hosted."
  step "Application name: e.g. 'Vault viewer shared pages'."
  step "Public hostname: domain $CF_PAGES_HOST, path: s/   (production only; previews stay fully protected)."
  step "Add a policy: Action Bypass; Include > Everyone. Nothing else. Save the application."
  warn "Bypass belongs ONLY on this /s/ application. Leave the $CF_PAGES_HOST application as it is (Allow, your email)."
  note "Access applies the application with the most specific path, so only /s/ skips the login."
  note "The site also puts its CSS and fonts under /s/_astro/ so shared pages are styled; they hold no vault content."
  pause "Bypass application saved? Press Enter to check it"
  share_gate "$CF_PAGES_HOST"
  say "And the rest of the site must still turn strangers away:"
  access_gate "$CF_PAGES_HOST"
else
  SKIPPED+=("Shared pages: re-run this wizard to set SHARE_SECRET and the /s/ Access application when you want them")
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Build your real vault and deploy it"
ask VAULT_DIR "Vault directory (Enter for $HOME/Documents/Obsidian):"
VAULT_DIR="${VAULT_DIR:-$HOME/Documents/Obsidian}"
[[ -d "$VAULT_DIR" ]] || { warn "No such directory: $VAULT_DIR"; exit 1; }
if ! confirm "Build $VAULT_DIR and upload it to $CF_PAGES_HOST?"; then
  warn "Stopped before uploading. Re-run when ready."; exit 0
fi
# An empty SHARE_SECRET (sharing skipped) builds with sharing off.
SHARE_SECRET="$SHARE_SECRET" VAULT_DIR="$VAULT_DIR" bun run build
say "Re-checking protection right before upload:"
access_gate "$CF_PAGES_HOST"
wr pages deploy dist --project-name "$CF_PAGES_PROJECT" --branch main
say "And once more now that real content is live:"
access_gate "$CF_PAGES_HOST"
step "On your phone, open https://$CF_PAGES_HOST , log in with GitHub, and check your notes show."
note "Done when: the phone shows notes after GitHub login (#13)."
pause

finish

